-- Progress: weigh-ins (BRD §4.2; implementation plan §4; R1 PR 3).
--
-- One row per weigh-in, on the member's local date; a member may weigh in more than once a day. The member reads and
-- writes; a coach or clinician with an active `body_metrics` grant reads (BRD §3.2 "Weight & measurements").

create table progress.body_weights (
  -- Generated by the client, so a retried save inserts nothing new (implementation plan §3.2).
  id uuid primary key,
  member_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  measured_on date not null,
  weight_kg numeric(5, 2) not null check (weight_kg between 20 and 500),
  created_at timestamptz not null default now()
);

create index body_weights_member on progress.body_weights (member_id, measured_on);

alter table progress.body_weights enable row level security;

create policy body_weights_select on progress.body_weights for select to authenticated
  using (member_id = (select auth.uid()) or care.has_grant(member_id, 'body_metrics'));
create policy body_weights_insert_own on progress.body_weights for insert to authenticated
  with check (member_id = (select auth.uid()));
create policy body_weights_update_own on progress.body_weights for update to authenticated
  using (member_id = (select auth.uid())) with check (member_id = (select auth.uid()));
create policy body_weights_delete_own on progress.body_weights for delete to authenticated
  using (member_id = (select auth.uid()));

grant usage on schema progress to authenticated;
grant select, insert, update, delete on progress.body_weights to authenticated;
